contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // A minimal token stub living in this test contract: transferFrom is a no-op that succeeds.
    fallback() external payable {
        assembly { mstore(0, 1) return(0, 32) }
    }

    function run(address token, address from, uint v) public payable {
        require(token != address(0));
        require(address(this).balance == address(this).balance); // no ether needed

        address[] memory tos = new address[](2);
        tos[0] = address(this);
        tos[1] = address(this);
        uint[] memory vals = new uint[](2);
        vals[0] = v;
        vals[1] = v;

        // Top-level state-changing call; the token is this contract, whose fallback
        // makes every transferFrom succeed, so the call must not revert.
        bool ok = c.transfer(from, token, tos, vals);

        // General rule: whenever all transferFrom calls succeed, transfer returns exactly true.
        assert(ok == true);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address token, address from, uint v, uint n) public payable {
        // token with no code: any low-level call to it succeeds with empty return data,
        // so every transferFrom inside c.transfer succeeds.
        require(token.code.length == 0);
        require(n > 0);

        address[] memory tos = new address[](n);
        uint[] memory vals = new uint[](n);
        for (uint i = 0; i < n; i++) {
            tos[i] = address(this);
            vals[i] = v;
        }

        // Top-level state-changing call: must not revert since all inner calls succeed.
        bool ok = c.transfer(from, token, tos, vals);

        // General rule: when every transferFrom succeeds, transfer returns exactly true.
        assert(ok == true);
    }
}

